06---Índices/📋-Índice-de-Habilidades.content:
📋 Mapa de Habilidades do Grupo
TABLE
  categoria AS &quot;Categoria&quot;,
  nivel_demanda AS &quot;Demanda&quot;
FROM &quot;02 - Habilidades&quot;
SORT categoria ASC, file.name ASC

🔗 Por categoria
Design &amp; Criação
LIST
FROM &quot;02 - Habilidades&quot;
WHERE categoria = &quot;design&quot;
SORT file.name ASC
Tecnologia &amp; Desenvolvimento
LIST
FROM &quot;02 - Habilidades&quot;
WHERE categoria = &quot;tecnologia&quot;
SORT file.name ASC
Negócios &amp; Estratégia
LIST
FROM &quot;02 - Habilidades&quot;
WHERE categoria = &quot;negocios&quot;
SORT file.name ASC
Marketing &amp; Comunicação
LIST
FROM &quot;02 - Habilidades&quot;
WHERE categoria = &quot;marketing&quot;
SORT file.name ASC
Outros
LIST
FROM &quot;02 - Habilidades&quot;
WHERE !contains(list(&quot;design&quot;,&quot;tecnologia&quot;,&quot;negocios&quot;,&quot;marketing&quot;), categoria)
SORT file.name ASC

06---Índices/📋-Índice-de-Projetos.content:
📋 Projetos do Grupo
🟢 Ativos
TABLE
  membros AS &quot;Equipe&quot;,
  skills_necessarias AS &quot;Skills abertas&quot;,
  data_inicio AS &quot;Início&quot;
FROM &quot;03 - Projetos&quot;
WHERE status = &quot;ativo&quot;
SORT data_inicio DESC
🔵 Em formação (buscando membros)
TABLE
  skills_necessarias AS &quot;Skills necessárias&quot;,
  tipo_colaboracao AS &quot;Tipo&quot;
FROM &quot;03 - Projetos&quot;
WHERE status = &quot;formando&quot;
✅ Concluídos
LIST
FROM &quot;03 - Projetos&quot;
WHERE status = &quot;concluido&quot;
